CREATE TABLE `locale_file` (   `project` varchar(255) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL DEFAULT '' COMMENT 'A unique short name to identify the project the file belongs to.',   `langcode` varchar(12) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL DEFAULT '' COMMENT 'Language code of this translation. References language.langcode.',   `filename` varchar(255) NOT NULL DEFAULT '' COMMENT 'Filename of the imported file.',   `version` varchar(128) NOT NULL DEFAULT '' COMMENT 'Version tag of the imported file.',   `uri` varchar(255) NOT NULL DEFAULT '' COMMENT 'URI of the remote file, the resulting local file or the locally imported file.',   `timestamp` int DEFAULT '0' COMMENT 'Unix timestamp of the imported file.',   `last_checked` int DEFAULT '0' COMMENT 'Unix timestamp of the last time this translation was confirmed to be the most recent release available.',   PRIMARY KEY (`project`,`langcode`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='File import status information for interface translation…';
DROP TABLE IF EXISTS `locales_location`;
CREATE TABLE `locales_location` (   `lid` int NOT NULL AUTO_INCREMENT COMMENT 'Unique identifier of this location.',   `sid` int NOT NULL COMMENT 'Unique identifier of this string.',   `type` varchar(50) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL DEFAULT '' COMMENT 'The location type (file, config, path, etc).',   `name` varchar(255) NOT NULL DEFAULT '' COMMENT 'Type dependent location information (file name, path, etc).',   `version` varchar(20) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL DEFAULT 'none' COMMENT 'Version of Drupal where the location was found.',   PRIMARY KEY (`lid`),   KEY `string_id` (`sid`),   KEY `string_type` (`sid`,`type`) ) ENGINE=InnoDB AUTO_INCREMENT=6256 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Location information for source strings.' AUTO_INCREMENT=6256;
DROP TABLE IF EXISTS `locales_source`;
