DROP TABLE IF EXISTS `xmlsitemap`;
CREATE TABLE `xmlsitemap` (   `id` varchar(32) NOT NULL DEFAULT '' COMMENT 'Primary key with type. a unique id for the item.',   `type` varchar(32) NOT NULL DEFAULT '' COMMENT 'Primary key with id. the type of item (e.g. node, user, etc.).',   `subtype` varchar(128) NOT NULL DEFAULT '' COMMENT 'A sub-type identifier for the link (node type, menu name, term VID, etc.).',   `loc` varchar(255) NOT NULL DEFAULT '' COMMENT 'The URL to the item relative to the Drupal path.',   `language` varchar(12) NOT NULL DEFAULT '' COMMENT 'The languages.language of this link or an empty string if it is language-neutral.',   `access` tinyint NOT NULL DEFAULT '1' COMMENT 'A boolean that represents if the item is viewable by the anonymous user. This field is useful to store the result of node_access() so we can retain changefreq and priority_override information.',   `status` tinyint NOT NULL DEFAULT '1' COMMENT 'An integer that represents if the item is included in the sitemap.',   `status_override` tinyint NOT NULL DEFAULT '0' COMMENT 'A boolean that if TRUE means that the status field has been overridden from its default value.',   `lastmod` int unsigned NOT NULL DEFAULT '0' COMMENT 'The UNIX timestamp of last modification of the item.',   `priority` float DEFAULT NULL COMMENT 'The priority of this URL relative to other URLs on your site. Valid values range from 0.0 to 1.0.',   `priority_override` tinyint NOT NULL DEFAULT '0' COMMENT 'A boolean that if TRUE means that the priority field has been overridden from its default value.',   `changefreq` int unsigned NOT NULL DEFAULT '0' COMMENT 'The average time in seconds between changes of this item.',   `changecount` int unsigned NOT NULL DEFAULT '0' COMMENT 'The number of times this item has been changed. Used to help calculate the next changefreq value.',   PRIMARY KEY (`id`,`type`,`language`),   KEY `loc` (`loc`(191)),   KEY `access_status_loc` (`access`,`status`,`loc`(191)),   KEY `type_subtype` (`type`,`subtype`) ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='The base table for xmlsitemap links.';


